def filter_authorized_chunks(chunks: list[dict], tenant_id: str, user_roles: set[str]) -> list[dict]:
    """Enforces tenant + user/document ACL before any chunk enters LLM context."""
    return [
        c for c in chunks
        if not c.get("deleted_at")
        and c.get("tenant_id") == tenant_id
        and (c.get("visibility") == "tenant_public" or bool(set(c.get("allowed_roles", [])) & user_roles))
    ]

def choose_execution_path(query_type: str) -> str:
    """Routes exact transactional lookups to SQL/API and documentary queries to Hybrid RAG."""
    if query_type == "transactional_state":
        return "authorized_sql_api"
    if query_type == "document_policy":
        return "hybrid_rag_with_citations"
    return "abstain_or_clarify"

